import subprocess,os
from PIL import Image
from ui import *
def sk(w,h): return f'<div class="sk" style="width:{w};height:{h}px"></div>'
def panel(t,body,note): return f'<div class="card" style="display:flex;flex-direction:column;gap:14px;min-height:0"><h2 style="margin:0">{t}</h2><div style="flex:1;display:flex;flex-direction:column;gap:12px;justify-content:center">{body}</div><div class="muted" style="font-size:14px;line-height:1.45">{note}</div></div>'
def build(th):
    load=f'<div style="display:flex;flex-direction:column;gap:12px">{sk("40%",14)}{sk("60%",36)}{sk("100%",64)}</div>'
    emp=f'<div style="display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center"><span style="width:44px;color:var(--muted)">{ic("inbox")}</span><b style="font-size:18px">Nenhum alerta ativo</b><span class="muted" style="font-size:16px">Nenhum distrito está sob alerta no período. Amplie o período para ver o histórico.</span><a class="btn s" href="#">Ver últimas 24 h</a></div>'
    err=f'<div style="display:flex;flex-direction:column;gap:10px;border:1px solid var(--t-critico);border-radius:12px;padding:16px;background:var(--elev)"><div style="display:flex;gap:10px;align-items:center;font-weight:600;color:var(--t-critico);font-size:16px"><span style="width:22px">{ic("warn")}</span>Não foi possível carregar o mapa</div><span class="muted" style="font-size:16px">A fonte CEMADEN não respondeu. Mostrando a última atualização, de 02/11 09:10.</span><span><a class="btn s" href="#">{ic("refresh")}Tentar novamente</a></span></div>'
    foc=f'<div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center"><span class="chip ctl focused">Ambiental</span><a class="btn p focused" href="#">Explorar o mapa</a></div><div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center"><span class="chip ctl" style="background:var(--elev);border-color:var(--text)">Hover</span><a class="btn p dis" href="#">Desativado</a></div>'
    dados=f'<div style="display:flex;flex-direction:column;gap:12px"><span class="chip ex" style="align-self:flex-start">Dados de exemplo</span><div class="mono" style="font-size:16px">Sem dado: <span style="display:inline-block;width:18px;height:18px;vertical-align:middle;background:var(--nodata);border:1px dashed var(--border-strong);border-radius:4px"></span> distrito sem medição na semana</div></div>'
    tip=f'<div style="display:flex;gap:16px;flex-wrap:wrap">{legend_items()}</div><div style="display:flex;gap:16px">'+''.join(f'<span class="badge b-{c}">{LAB[c]}</span>' for c in ('baixo','moderado','alto','critico'))+'</div>'
    ps=[panel('Carregando (skeleton)',load,'Estrutura do card visível, sem spinner; o brilho para com prefers-reduced-motion.'),panel('Vazio',emp,'Diz o que aconteceu e oferece uma ação.'),panel('Erro',err,'Causa, o que o usuário vê agora e como tentar de novo.'),panel('Foco, hover e desativado',foc,'Foco visível: anel de 2 px (--ring) com 2 px de offset. Alvos de toque ≥ 44 px.'),panel('Sem dado e dados de exemplo',dados,'O rótulo “Dados de exemplo” aparece em toda tela.'),panel('Risco: cor + forma + rótulo',tip,'Cada classe tem cor, padrão/forma e texto; nunca só cor.')]
    return f'<div class="{th}" style="width:1920px;height:1080px;background:var(--bg);color:var(--text);padding:36px 40px;display:flex;flex-direction:column;gap:24px"><div style="display:flex;align-items:center;gap:12px">{logo(36)}<div style="font-size:28px;font-weight:600">EcoGuard · Estados de interface</div><span class="chip ex" style="margin-left:auto">Dados de exemplo</span></div><div style="display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:1fr 1fr;gap:24px;flex:1;min-height:0">{"".join(ps)}</div></div>'
os.makedirs('../mockups/extras',exist_ok=True)
for th,nm in [('dark','escuro'),('light','claro')]:
    h=f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><style>{CSS}body{{display:block}}</style></head><body class="{th}">{build(th)}<svg width="0" height="0" style="position:absolute">{PATDEFS}</svg></body></html>'
    p=f'../html/estados-{nm}.html'; open(p,'w').write(h)
    subprocess.run(['google-chrome','--headless=new','--no-sandbox','--disable-gpu','--hide-scrollbars','--force-device-scale-factor=1','--window-size=1920,1167','--virtual-time-budget=2000','--screenshot=/tmp/es.png','file:///workspace/ecoguard-design/html/'+os.path.basename(p)],capture_output=True)
    Image.open('/tmp/es.png').crop((0,0,1920,1080)).save(f'../mockups/extras/estados-{nm}.png')
